            elif is_digit1:
                # Numeric identifier sorts before non-numeric
                return -1
            elif is_digit2:
                # Non-numeric identifier sorts after numeric
                return 1
            else:
                # Both are non-numeric, compare lexically
                if id1 < id2:
                    return -1
                elif id1 > id2:
                    return 1

        # If all shared identifiers are equal, fewer identifiers sorts first
        if len(pre1) < len(pre2):
            return -1
        elif len(pre1) > len(pre2):
            return 1
        return 0

