        index, version = item
        major, minor, patch, prerelease = parse_version(version)
        # Return tuple for sorting: (major, minor, patch, prerelease_sort_key, original_index)
        # For prerelease, we need a value that sorts appropriately
        if prerelease is None:
            prerelease_key = (1,)  # No pre-release sorts after pre-release
        else:
            # Create a comparable key for pre-release identifiers
            prerelease_key = (0, prerelease)

        return (major, minor, patch, prerelease_key, index)

