        idx2, v2 = item2

        parsed1 = parse_version(v1)
        parsed2 = parse_version(v2)

        major1, minor1, patch1, pre1 = parsed1
        major2, minor2, patch2, pre2 = parsed2

        # Compare MAJOR.MINOR.PATCH
        if major1 != major2:
            return -1 if major1 < major2 else 1
        if minor1 != minor2:
            return -1 if minor1 < minor2 else 1
        if patch1 != patch2:
            return -1 if patch1 < patch2 else 1

        # Compare pre-release
        pre_cmp = compare_prerelease(pre1, pre2)
        if pre_cmp != 0:
            return pre_cmp

        # If equal precedence, maintain input order
        return -1 if idx1 < idx2 else (1 if idx1 > idx2 else 0)

    sorted_versions = sorted(indexed_versions, key=cmp_to_key(compare_versions))
    return [v for _, v in sorted_versions]

